    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, 'An 13-year-old child sustains a minor ankle sprain. Radiographs are negative for fracture but show an incidental, 2 cm, eccentric, bubbly, cortically based radiolucent lesion with a thin sclerotic margin in the distal tibial metaphysis. The patient has no pain directly over the lesion. What is the most appropriate management?', '["Reassurance and observation", "Prophylactic internal fixation", "MRI of the entire tibia", "Immediate core needle biopsy", "Curettage and bone grafting"]'::jsonb, 0, 'This classic description is a Non-Ossifying Fibroma (NOF) or Fibrous Cortical Defect. These are asymptomatic, developmental defects seen in up to 30-40% of normal children. They invariably resolve/ossify spontaneously over time and require only observation unless they are large enough (>50% of bone diameter) to pose a risk of pathologic fracture.'),
    (v_topic_id, 'A 61-year-old patient complains of severe pain in the pelvis. Imaging shows a ''punched-out'' lytic lesion. Blood work reveals anemia, hypercalcemia, and renal insufficiency. A serum protein electrophoresis (SPEP) is ordered. What is the expected mechanism of the bone destruction?', '["Ischemic necrosis of the medullary cavity", "Direct mechanical pressure from the tumor mass", "Neoplastic plasma cells secrete factors (like MIP-1 alpha and RANKL) that stimulate osteoclasts.", "Osteoblast overactivation", "Deposition of amyloid protein in the bone matrix"]'::jsonb, 2, 'In multiple myeloma, malignant plasma cells upregulate osteoclast activity (via RANKL and MIP-1 alpha) and downregulate osteoblast activity (via DKK-1), leading to pure lytic lesions without reactive new bone formation.'),
    (v_topic_id, 'A 65-year-old patient complains of severe pain in the femur. Imaging shows a ''punched-out'' lytic lesion. Blood work reveals anemia, hypercalcemia, and renal insufficiency. A serum protein electrophoresis (SPEP) is ordered. What is the expected mechanism of the bone destruction?', '["Neoplastic plasma cells secrete factors (like MIP-1 alpha and RANKL) that stimulate osteoclasts.", "Ischemic necrosis of the medullary cavity", "Direct mechanical pressure from the tumor mass", "Deposition of amyloid protein in the bone matrix", "Osteoblast overactivation"]'::jsonb, 0, 'In multiple myeloma, malignant plasma cells upregulate osteoclast activity (via RANKL and MIP-1 alpha) and downregulate osteoblast activity (via DKK-1), leading to pure lytic lesions without reactive new bone formation.'),
    (v_topic_id, 'A 31-year-old patient requires an open incisional biopsy for a suspected high-grade soft tissue sarcoma of the anterior thigh. Which of the following is a critical principle when performing this biopsy?', '["Use a transverse incision parallel to skin tension lines for a better cosmetic result", "Use a longitudinal incision placed within the planned definitive resection ellipse", "Obtain a small sample of the necrotic center rather than the periphery to ensure a diagnosis", "Dissect extensively through intermuscular planes to avoid muscle damage", "Exsanguinate the limb with an Esmarch bandage before inflating the tourniquet"]'::jsonb, 1, 'Orthopedic oncology biopsy principles: 1) Longitudinal incisions (transverse incisions contaminate more tissue longitudinally). 2) The biopsy tract must be excisable en bloc with the tumor. 3) Avoid spreading through fascial planes (split muscle instead). 4) Do NOT exsanguinate with an Esmarch to prevent pushing tumor cells centrally. 5) Biopsy the periphery (the advancing edge), as the center is often necrotic.'),
    (v_topic_id, 'A 31-year-old patient presents with a swollen, deformed hand. Radiographs show multiple centrally located radiolucent lesions with stippled calcifications within the phalanges and metacarpals. Physical exam reveals multiple soft tissue hemangiomas on the same limb. What is the diagnosis?', '["Ollier disease", "Neurofibromatosis type 1", "Multiple hereditary exostoses", "McCune-Albright syndrome", "Maffucci syndrome"]'::jsonb, 4, 'Enchondromas are benign cartilage tumors of the medullary cavity, frequently found in the small bones of the hands and feet. Multiple enchondromas alone characterize Ollier disease. When multiple enchondromas are accompanied by soft tissue hemangiomas, it is called Maffucci syndrome, which carries a much higher risk of malignant transformation to chondrosarcoma and other visceral malignancies.'),
    (v_topic_id, 'A 52-year-old patient requires an open incisional biopsy for a suspected high-grade soft tissue sarcoma of the anterior thigh. Which of the following is a critical principle when performing this biopsy?', '["Dissect extensively through intermuscular planes to avoid muscle damage", "Use a transverse incision parallel to skin tension lines for a better cosmetic result", "Exsanguinate the limb with an Esmarch bandage before inflating the tourniquet", "Use a longitudinal incision placed within the planned definitive resection ellipse", "Obtain a small sample of the necrotic center rather than the periphery to ensure a diagnosis"]'::jsonb, 3, 'Orthopedic oncology biopsy principles: 1) Longitudinal incisions (transverse incisions contaminate more tissue longitudinally). 2) The biopsy tract must be excisable en bloc with the tumor. 3) Avoid spreading through fascial planes (split muscle instead). 4) Do NOT exsanguinate with an Esmarch to prevent pushing tumor cells centrally. 5) Biopsy the periphery (the advancing edge), as the center is often necrotic.'),
    (v_topic_id, 'A 53-year-old patient complains of severe pain in the pelvis. Imaging shows a ''punched-out'' lytic lesion. Blood work reveals anemia, hypercalcemia, and renal insufficiency. A serum protein electrophoresis (SPEP) is ordered. What is the expected mechanism of the bone destruction?', '["Neoplastic plasma cells secrete factors (like MIP-1 alpha and RANKL) that stimulate osteoclasts.", "Deposition of amyloid protein in the bone matrix", "Direct mechanical pressure from the tumor mass", "Ischemic necrosis of the medullary cavity", "Osteoblast overactivation"]'::jsonb, 0, 'In multiple myeloma, malignant plasma cells upregulate osteoclast activity (via RANKL and MIP-1 alpha) and downregulate osteoblast activity (via DKK-1), leading to pure lytic lesions without reactive new bone formation.'),
    (v_topic_id, 'A 13-year-old presents with a painful, enlarging mass around the proximal tibia. Radiographs reveal a destructive, mixed lytic and blastic lesion in the metaphysis, with a ''sunburst'' periosteal reaction and a Codman triangle. A biopsy shows malignant cells producing unmineralized osteoid. Which of the following is the standard treatment protocol?', '["Neoadjuvant chemotherapy, surgical resection, and adjuvant chemotherapy", "Surgical resection alone", "Primary radiation therapy followed by resection", "Neoadjuvant radiation and chemotherapy without surgery", "Curettage, phenol adjuvant, and cementation"]'::jsonb, 0, 'Osteosarcoma is the most common primary bone malignancy in adolescents. It typically occurs in the metaphysis of long bones. Histologic hallmark is the production of osteoid by malignant cells. Standard treatment is neoadjuvant (preoperative) chemotherapy, wide surgical resection (limb salvage), followed by adjuvant chemotherapy based on tumor necrosis rate.'),
    (v_topic_id, 'A 77-year-old male presents with severe back pain. Radiographs of the lumbar spine show a dense, sclerotic (osteoblastic) lesion in the L3 vertebral body. Laboratory studies show an elevated alkaline phosphatase, but normal calcium. Which primary malignancy is most likely responsible for this metastatic lesion?', '["Malignant melanoma", "Multiple myeloma", "Thyroid carcinoma", "Prostate carcinoma", "Renal cell carcinoma"]'::jsonb, 3, 'Metastatic prostate cancer characteristically produces osteoblastic (sclerotic) bone lesions due to the secretion of factors that stimulate bone formation (like BMPs). Conversely, cancers like renal cell, thyroid, and multiple myeloma typically cause osteolytic (destructive) lesions.'),
    (v_topic_id, 'A 56-year-old patient requires an open incisional biopsy for a suspected high-grade soft tissue sarcoma of the anterior thigh. Which of the following is a critical principle when performing this biopsy?', '["Use a transverse incision parallel to skin tension lines for a better cosmetic result", "Exsanguinate the limb with an Esmarch bandage before inflating the tourniquet", "Obtain a small sample of the necrotic center rather than the periphery to ensure a diagnosis", "Dissect extensively through intermuscular planes to avoid muscle damage", "Use a longitudinal incision placed within the planned definitive resection ellipse"]'::jsonb, 4, 'Orthopedic oncology biopsy principles: 1) Longitudinal incisions (transverse incisions contaminate more tissue longitudinally). 2) The biopsy tract must be excisable en bloc with the tumor. 3) Avoid spreading through fascial planes (split muscle instead). 4) Do NOT exsanguinate with an Esmarch to prevent pushing tumor cells centrally. 5) Biopsy the periphery (the advancing edge), as the center is often necrotic.'),
    (v_topic_id, 'A 62-year-old male presents with severe back pain. Radiographs of the lumbar spine show a dense, sclerotic (osteoblastic) lesion in the L3 vertebral body. Laboratory studies show an elevated alkaline phosphatase, but normal calcium. Which primary malignancy is most likely responsible for this metastatic lesion?', '["Prostate carcinoma", "Thyroid carcinoma", "Renal cell carcinoma", "Malignant melanoma", "Multiple myeloma"]'::jsonb, 0, 'Metastatic prostate cancer characteristically produces osteoblastic (sclerotic) bone lesions due to the secretion of factors that stimulate bone formation (like BMPs). Conversely, cancers like renal cell, thyroid, and multiple myeloma typically cause osteolytic (destructive) lesions.'),
    (v_topic_id, 'A 19-year-old patient has intense nocturnal pain in the humerus that responds dramatically to naproxen. Imaging confirms a nidus with surrounding sclerosis. If the patient opts for minimally invasive intervention, what is the treatment of choice?', '["Cryoablation without imaging", "Intra-articular steroid injection", "CT-guided radiofrequency ablation (RFA)", "Radiation therapy", "Open en bloc resection"]'::jsonb, 2, 'Osteoid osteomas are benign bone-forming tumors. While they can ''''burn out'''' spontaneously over years, symptomatic patients who cannot tolerate long-term NSAIDs are best treated with percutaneous, CT-guided radiofrequency ablation, which has a very high success rate.'),
    (v_topic_id, 'A 17-year-old patient has intense nocturnal pain in the radius that responds dramatically to naproxen. Imaging confirms a nidus with surrounding sclerosis. If the patient opts for minimally invasive intervention, what is the treatment of choice?', '["Open en bloc resection", "Intra-articular steroid injection", "CT-guided radiofrequency ablation (RFA)", "Cryoablation without imaging", "Radiation therapy"]'::jsonb, 2, 'Osteoid osteomas are benign bone-forming tumors. While they can ''''burn out'''' spontaneously over years, symptomatic patients who cannot tolerate long-term NSAIDs are best treated with percutaneous, CT-guided radiofrequency ablation, which has a very high success rate.'),
    (v_topic_id, 'A 20-year-old male presents with deep, aching pain in the proximal femur that is characteristically worse at night. The pain is completely relieved by ibuprofen. Radiographs show a small (< 1.5 cm) radiolucent nidus surrounded by dense reactive sclerosis. What is the most appropriate definitive management if symptoms become refractory?', '["Wide surgical resection", "Curettage and bone grafting", "Radiofrequency ablation (RFA)", "Radiation therapy", "Chemotherapy followed by limb-salvage surgery"]'::jsonb, 2, 'Osteoid osteoma classically presents with night pain relieved by NSAIDs due to high prostaglandin (PGE2) production by the tumor nidus. CT is the best imaging modality to visualize the nidus. If medical management fails or is poorly tolerated, percutaneous radiofrequency ablation (RFA) is the treatment of choice.'),
    (v_topic_id, 'A 13-year-old patient is diagnosed with high-grade conventional osteosarcoma of the distal radius. They are scheduled for a limb-salvage procedure. According to standard protocol, what must precede the surgical resection?', '["Radiation therapy", "Bisphosphonates", "Denosumab", "Amputation", "Neoadjuvant chemotherapy"]'::jsonb, 4, 'Standard treatment for high-grade osteosarcoma includes neoadjuvant (preoperative) chemotherapy, which targets micrometastases and shrinks the tumor, followed by wide surgical resection and adjuvant chemotherapy.'),
    (v_topic_id, 'A 54-year-old patient presents with a slowly worsening ache in the proximal humerus. Radiographs show a large, poorly defined intramedullary lesion with endosteal scalloping and prominent ''popcorn'' or ''ring-and-arc'' calcifications. Biopsy confirms malignant cartilage. What is the primary modality of treatment?', '["Systemic chemotherapy", "High-dose radiation therapy", "Denosumab therapy", "Radiofrequency ablation", "Wide surgical resection"]'::jsonb, 4, 'Chondrosarcomas are malignant tumors of cartilage typically seen in older adults (pelvis, proximal femur). They are notoriously resistant to both chemotherapy and radiation therapy. Therefore, wide surgical excision is the mainstay of treatment for conventional chondrosarcomas.'),
    (v_topic_id, 'A 7-year-old patient has intense nocturnal pain in the humerus that responds dramatically to naproxen. Imaging confirms a nidus with surrounding sclerosis. If the patient opts for minimally invasive intervention, what is the treatment of choice?', '["Open en bloc resection", "Cryoablation without imaging", "Intra-articular steroid injection", "Radiation therapy", "CT-guided radiofrequency ablation (RFA)"]'::jsonb, 4, 'Osteoid osteomas are benign bone-forming tumors. While they can ''''burn out'''' spontaneously over years, symptomatic patients who cannot tolerate long-term NSAIDs are best treated with percutaneous, CT-guided radiofrequency ablation, which has a very high success rate.'),
    (v_topic_id, 'A 10-year-old presents with a painless, hard bump near the knee. Radiographs show a bony outgrowth from the distal femoral metaphysis that points away from the joint. The medullary cavity of the lesion is continuous with the medullary cavity of the native bone. What is the most feared complication if this patient has multiple similar lesions?', '["Pathologic fracture through the stalk", "Systemic metastasis to the lungs", "Malignant transformation to secondary chondrosarcoma", "Malignant transformation to osteosarcoma", "Development of multiple myeloma"]'::jsonb, 2, 'This is an osteochondroma. While solitary osteochondromas have a <1% risk of malignant transformation, patients with Multiple Hereditary Exostoses (EXT1/EXT2 mutations) have a higher risk (up to 5-10%) of a lesion degenerating into a secondary chondrosarcoma. A rapidly growing or painful cartilage cap (> 2 cm in an adult) is a warning sign.'),
    (v_topic_id, 'A 20-year-old patient presents with rapid swelling of the femur. Radiographs show an eccentric, expansile metaphyseal lesion. MRI shows multiple fluid-fluid levels. What does this MRI finding represent?', '["Necrotic tumor debris", "Separation of cellular blood components from serum", "Fat floating on water within a lipoma", "Contrast pooling in a hemangioma", "Pus settling from an abscess"]'::jsonb, 1, 'The ''''fluid-fluid level'''' on MRI in an aneurysmal bone cyst (ABC) represents the settling of red blood cells out of serum in the cyst''''s cavernous, blood-filled spaces.'),
    (v_topic_id, 'A 70-year-old patient presents with a slowly worsening ache in the proximal humerus. Radiographs show a large, poorly defined intramedullary lesion with endosteal scalloping and prominent ''popcorn'' or ''ring-and-arc'' calcifications. Biopsy confirms malignant cartilage. What is the primary modality of treatment?', '["Radiofrequency ablation", "Wide surgical resection", "High-dose radiation therapy", "Denosumab therapy", "Systemic chemotherapy"]'::jsonb, 1, 'Chondrosarcomas are malignant tumors of cartilage typically seen in older adults (pelvis, proximal femur). They are notoriously resistant to both chemotherapy and radiation therapy. Therefore, wide surgical excision is the mainstay of treatment for conventional chondrosarcomas.'),
    (v_topic_id, 'A 19-year-old patient has intense nocturnal pain in the pelvis that responds dramatically to naproxen. Imaging confirms a nidus with surrounding sclerosis. If the patient opts for minimally invasive intervention, what is the treatment of choice?', '["CT-guided radiofrequency ablation (RFA)", "Radiation therapy", "Cryoablation without imaging", "Intra-articular steroid injection", "Open en bloc resection"]'::jsonb, 0, 'Osteoid osteomas are benign bone-forming tumors. While they can ''''burn out'''' spontaneously over years, symptomatic patients who cannot tolerate long-term NSAIDs are best treated with percutaneous, CT-guided radiofrequency ablation, which has a very high success rate.'),
    (v_topic_id, 'A 69-year-old patient presents with back pain and fatigue. Radiographs of the skull and spine show multiple ''punched-out'' radiolucencies without any surrounding reactive sclerosis. Laboratory tests reveal hypercalcemia, anemia, and an M-spike on serum protein electrophoresis. Which bone scan finding is expected?', '["Diffuse periosteal uptake", "A ''superscan'' with absent renal visualization", "Intensely increased uptake (''hot'' spots) in all lesions", "A falsely negative (''cold'' or normal) bone scan", "Increased uptake exclusively in the appendicular skeleton"]'::jsonb, 3, 'Multiple myeloma lesions are purely osteolytic, caused by myeloma cells stimulating osteoclasts (via RANKL) and actively inhibiting osteoblasts (via DKK-1). Because a Technetium-99m bone scan relies on osteoblastic activity (bone formation), it is notoriously unreliable (falsely negative) in multiple myeloma. A skeletal survey (plain films) or low-dose whole-body CT is the preferred imaging modality.'),
    (v_topic_id, 'A 5-year-old patient presents with rapid swelling of the tibia. Radiographs show an eccentric, expansile metaphyseal lesion. MRI shows multiple fluid-fluid levels. What does this MRI finding represent?', '["Necrotic tumor debris", "Fat floating on water within a lipoma", "Separation of cellular blood components from serum", "Pus settling from an abscess", "Contrast pooling in a hemangioma"]'::jsonb, 2, 'The ''''fluid-fluid level'''' on MRI in an aneurysmal bone cyst (ABC) represents the settling of red blood cells out of serum in the cyst''''s cavernous, blood-filled spaces.'),
    (v_topic_id, 'A 19-year-old presents with a painful, enlarging mass around the distal femur. Radiographs reveal a destructive, mixed lytic and blastic lesion in the metaphysis, with a ''sunburst'' periosteal reaction and a Codman triangle. A biopsy shows malignant cells producing unmineralized osteoid. Which of the following is the standard treatment protocol?', '["Surgical resection alone", "Neoadjuvant chemotherapy, surgical resection, and adjuvant chemotherapy", "Curettage, phenol adjuvant, and cementation", "Neoadjuvant radiation and chemotherapy without surgery", "Primary radiation therapy followed by resection"]'::jsonb, 1, 'Osteosarcoma is the most common primary bone malignancy in adolescents. It typically occurs in the metaphysis of long bones. Histologic hallmark is the production of osteoid by malignant cells. Standard treatment is neoadjuvant (preoperative) chemotherapy, wide surgical resection (limb salvage), followed by adjuvant chemotherapy based on tumor necrosis rate.'),
    (v_topic_id, 'A 13-year-old patient is diagnosed with high-grade conventional osteosarcoma of the distal tibia. They are scheduled for a limb-salvage procedure. According to standard protocol, what must precede the surgical resection?', '["Amputation", "Bisphosphonates", "Neoadjuvant chemotherapy", "Radiation therapy", "Denosumab"]'::jsonb, 2, 'Standard treatment for high-grade osteosarcoma includes neoadjuvant (preoperative) chemotherapy, which targets micrometastases and shrinks the tumor, followed by wide surgical resection and adjuvant chemotherapy.'),
    (v_topic_id, 'A 8-year-old patient is diagnosed with high-grade conventional osteosarcoma of the distal humerus. They are scheduled for a limb-salvage procedure. According to standard protocol, what must precede the surgical resection?', '["Radiation therapy", "Denosumab", "Amputation", "Bisphosphonates", "Neoadjuvant chemotherapy"]'::jsonb, 4, 'Standard treatment for high-grade osteosarcoma includes neoadjuvant (preoperative) chemotherapy, which targets micrometastases and shrinks the tumor, followed by wide surgical resection and adjuvant chemotherapy.'),
    (v_topic_id, 'A 72-year-old male presents with severe back pain. Radiographs of the lumbar spine show a dense, sclerotic (osteoblastic) lesion in the L3 vertebral body. Laboratory studies show an elevated alkaline phosphatase, but normal calcium. Which primary malignancy is most likely responsible for this metastatic lesion?', '["Renal cell carcinoma", "Prostate carcinoma", "Multiple myeloma", "Malignant melanoma", "Thyroid carcinoma"]'::jsonb, 1, 'Metastatic prostate cancer characteristically produces osteoblastic (sclerotic) bone lesions due to the secretion of factors that stimulate bone formation (like BMPs). Conversely, cancers like renal cell, thyroid, and multiple myeloma typically cause osteolytic (destructive) lesions.'),
    (v_topic_id, 'A 7-year-old patient is diagnosed with high-grade conventional osteosarcoma of the distal femur. They are scheduled for a limb-salvage procedure. According to standard protocol, what must precede the surgical resection?', '["Denosumab", "Amputation", "Radiation therapy", "Neoadjuvant chemotherapy", "Bisphosphonates"]'::jsonb, 3, 'Standard treatment for high-grade osteosarcoma includes neoadjuvant (preoperative) chemotherapy, which targets micrometastases and shrinks the tumor, followed by wide surgical resection and adjuvant chemotherapy.'),
    (v_topic_id, 'A 12-year-old male presents with deep, aching pain in the posterior spine that is characteristically worse at night. The pain is completely relieved by ibuprofen. Radiographs show a small (< 1.5 cm) radiolucent nidus surrounded by dense reactive sclerosis. What is the most appropriate definitive management if symptoms become refractory?', '["Chemotherapy followed by limb-salvage surgery", "Radiofrequency ablation (RFA)", "Wide surgical resection", "Curettage and bone grafting", "Radiation therapy"]'::jsonb, 1, 'Osteoid osteoma classically presents with night pain relieved by NSAIDs due to high prostaglandin (PGE2) production by the tumor nidus. CT is the best imaging modality to visualize the nidus. If medical management fails or is poorly tolerated, percutaneous radiofrequency ablation (RFA) is the treatment of choice.'),
    (v_topic_id, 'A 62-year-old patient presents with a slowly worsening ache in the pelvis. Radiographs show a large, poorly defined intramedullary lesion with endosteal scalloping and prominent ''popcorn'' or ''ring-and-arc'' calcifications. Biopsy confirms malignant cartilage. What is the primary modality of treatment?', '["Wide surgical resection", "Denosumab therapy", "Radiofrequency ablation", "Systemic chemotherapy", "High-dose radiation therapy"]'::jsonb, 0, 'Chondrosarcomas are malignant tumors of cartilage typically seen in older adults (pelvis, proximal femur). They are notoriously resistant to both chemotherapy and radiation therapy. Therefore, wide surgical excision is the mainstay of treatment for conventional chondrosarcomas.'),
    (v_topic_id, 'A 62-year-old female with a history of breast cancer presents with a pathologic fracture of the proximal humerus. The lesion is lytic. What is the primary goal of orthopedic stabilization in this setting?', '["Achieving a biologic union of the fracture site without cement", "Curative resection of the tumor with wide margins", "Immediate pain relief, early mobilization, and restoration of function", "Delaying surgery until radiation therapy is completed", "Preventing pulmonary metastasis"]'::jsonb, 2, 'The treatment of metastatic pathologic fractures is generally palliative. The goals are to provide immediate mechanical stability (often using intramedullary nails and cement), relieve pain, and allow early weight-bearing and functional independence.'),
    (v_topic_id, 'A 10-year-old boy falls and sustains a pathologic fracture of the proximal humerus. Radiographs show a centrally located, lytic lesion in the metaphysis that is well-marginated. A fragment of cortical bone is seen resting at the bottom of the cystic cavity. What is the most likely diagnosis?', '["Fibrous dysplasia", "Non-ossifying fibroma", "Aneurysmal Bone Cyst", "Osteosarcoma", "Unicameral (Simple) Bone Cyst"]'::jsonb, 4, 'The ''''fallen leaf'''' or ''''fallen fragment'''' sign is pathognomonic for a Unicameral Bone Cyst (UBC). When a pathologic fracture occurs, a piece of cortical bone breaks off and sinks through the serous fluid to the bottom of the cyst. An ABC would be eccentric, expansile, and contain blood.'),
    (v_topic_id, 'A 81-year-old patient complains of severe pain in the pelvis. Imaging shows a ''punched-out'' lytic lesion. Blood work reveals anemia, hypercalcemia, and renal insufficiency. A serum protein electrophoresis (SPEP) is ordered. What is the expected mechanism of the bone destruction?', '["Neoplastic plasma cells secrete factors (like MIP-1 alpha and RANKL) that stimulate osteoclasts.", "Deposition of amyloid protein in the bone matrix", "Ischemic necrosis of the medullary cavity", "Direct mechanical pressure from the tumor mass", "Osteoblast overactivation"]'::jsonb, 0, 'In multiple myeloma, malignant plasma cells upregulate osteoclast activity (via RANKL and MIP-1 alpha) and downregulate osteoblast activity (via DKK-1), leading to pure lytic lesions without reactive new bone formation.'),
